//! Mathematical alphanumeric alphabets (`\mathbb`, `\mathcal`, …).
//!
//! From the `<font>` decompositions in UnicodeData.txt. The 24 reserved
//! holes in the Mathematical Alphanumeric Symbols block (ℎ ℬ ℰ ℱ ℋ ℐ ℒ ℳ ℛ
//! ℯ ℊ ℴ ℭ ℌ ℑ ℜ ℨ ℂ ℍ ℕ ℙ ℚ ℝ ℤ) are filled from Letterlike Symbols, as
//! are the double-struck Greek letters ℾ ℿ ℽ ℼ and ⅅ ⅆ ⅇ ⅈ ⅉ.
//!
//! Generated by `cargo xtask gen` from UCD 17.0.0; do not edit.

/// A mathematical alphanumeric style.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Alphabet {
    /// Bold (`\mathbf` with `Bold::Unicode`): 𝐀 𝐚 𝟎 𝚨 𝛂.
    Bold,
    /// Italic (`Letters::UnicodeItalic`): 𝐴 𝑎 𝛼, with ℎ for h.
    Italic,
    /// Bold italic (`\boldsymbol` with `Bold::Unicode`): 𝑨 𝒂 𝜶.
    BoldItalic,
    /// Script (`\mathcal`, `\mathscr`): 𝒜 ℬ 𝒶 ℯ.
    Script,
    /// Bold script (`\mathbfcal`): 𝓐 𝓪.
    BoldScript,
    /// Fraktur (`\mathfrak`): 𝔄 ℭ 𝔞.
    Fraktur,
    /// Bold Fraktur (`\mathbffrak`): 𝕬 𝖆.
    BoldFraktur,
    /// Double-struck (`\mathbb`): 𝔸 ℂ 𝕒 𝟙 ℾ.
    DoubleStruck,
    /// Double-struck italic (`\mathbbit`): only ⅅ ⅆ ⅇ ⅈ ⅉ exist.
    DoubleStruckItalic,
}

impl Alphabet {
    /// Every alphabet, in declaration order.
    #[cfg(test)]
    pub(crate) const ALL: [Alphabet; 9] = [
        Alphabet::Bold,
        Alphabet::Italic,
        Alphabet::BoldItalic,
        Alphabet::Script,
        Alphabet::BoldScript,
        Alphabet::Fraktur,
        Alphabet::BoldFraktur,
        Alphabet::DoubleStruck,
        Alphabet::DoubleStruckItalic,
    ];

    /// `(base, styled)` pairs sorted by base.
    pub(crate) fn table(self) -> &'static [(char, char)] {
        match self {
            Alphabet::Bold => &BOLD,
            Alphabet::Italic => &ITALIC,
            Alphabet::BoldItalic => &BOLD_ITALIC,
            Alphabet::Script => &SCRIPT,
            Alphabet::BoldScript => &BOLD_SCRIPT,
            Alphabet::Fraktur => &FRAKTUR,
            Alphabet::BoldFraktur => &BOLD_FRAKTUR,
            Alphabet::DoubleStruck => &DOUBLE_STRUCK,
            Alphabet::DoubleStruckItalic => &DOUBLE_STRUCK_ITALIC,
        }
    }
}

